%[text] # Reducer Basic model - simulation case
model_name = "HarnessModel_Reducer";
load_system(model_name)

Reducer_Basic_params
loadLUTData_Reducer_Axle_FlipTorque
loadLUTData_Reducer_Motor_FlipTorque

sim_in = Simulink.SimulationInput(model_name);

sim_in = setModelParameter(sim_in, StopTime = "150");
%[text] Run simulation.
sim_out = sim(sim_in);

% Signal logging for Simulink blocks is configured in the Measurement subsystem of the harness model.
% Signal logging for Simscape blocks is configured in the setupLogging_*.m files.
signals = bevutil1.SignalUtil.getTimetableFromLoggedSignal(sim_out.logsout);
%[text] Visually inspect the simulation result.
varnames = string(signals.Properties.VariableNames);
for k = 1 : numel(varnames) %[output:group:24f5b430]
  bevutil1.SignalUtil.plotTimedData(TimedData=signals, SignalName=varnames(k), FigureHeight=200); %[output:3020811f] %[output:8003465b] %[output:473b978b] %[output:246a7351] %[output:545f3461] %[output:632b62e9] %[output:6b3628ef] %[output:71a48843] %[output:12ac486f] %[output:8ad3ef49] %[output:35228899] %[output:743acc82]
end  % for %[output:group:24f5b430]
